        const sourceUrl = await sourceUrlForLocalHttpBundle(imp.n, options.dependencyCacheRoot, options.readDependencySource);
        if (!sourceUrl)
            continue;
        const assetUrl = manifest ? dependencyAssetUrl(manifest, sourceUrl) : null;
